#!/usr/bin/env python3
"""JSON data cleaning pipeline: read JSON → clean → save CSV.

Cleaning steps:
  1. Drop rows where all values are missing
  2. Remove exact duplicate rows
  3. Strip whitespace from string values
  4. Coerce types (string numbers → int/float, booleans, dates)
  5. Fill remaining missing values (numeric → median/mean, string → "N/A")

Usage:
    python json_csv_pipeline.py input.json [-o output.csv] [--fill-strategy median|mean|drop]
"""

import argparse
import csv
import json
import re
import sys
from datetime import datetime
from pathlib import Path
from statistics import median, mean
from typing import Any


# ---------------------------------------------------------------------------
# Type detection / conversion
# ---------------------------------------------------------------------------

_MISSING = {None, "", "null", "NULL", "None", "N/A", "n/a", "NA", "na", "-", "--"}

_DATE_FORMATS = [
    "%Y-%m-%d",
    "%m/%d/%Y",
    "%d-%m-%Y",
    "%Y/%m/%d",
    "%b %d, %Y",
]


def _is_missing(value: Any) -> bool:
    if value is None:
        return True
    if isinstance(value, str) and value.strip() in _MISSING:
        return True
    return False


def _parse_date(value: str) -> str | None:
    value = value.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(value, fmt).strftime("%Y-%m-%d")
        except ValueError:
            continue
    return None


def _coerce_value(value: Any) -> Any:
    """Try bool → int → float → date → keep-as-string. None for missing."""
    if _is_missing(value):
        return None
    if isinstance(value, bool):
        return value
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return value
    if not isinstance(value, str):
        return value

    s = value.strip()
    if s in _MISSING:
        return None

    # bool
    if s.lower() in ("true", "yes"):
        return True
    if s.lower() in ("false", "no"):
        return False

    # int
    try:
        return int(s)
    except ValueError:
        pass

    # float
    try:
        return float(s)
    except ValueError:
        pass

    # date
    parsed = _parse_date(s)
    if parsed:
        return parsed

    return s


def _detect_column_type(values: list) -> str:
    """Return 'int', 'float', 'date', 'bool', or 'str' for a column."""
    non_null = [v for v in values if v is not None]
    if not non_null:
        return "str"

    if all(isinstance(v, bool) for v in non_null):
        return "bool"
    if all(isinstance(v, int) and not isinstance(v, bool) for v in non_null):
        return "int"
    if all(isinstance(v, (int, float)) and not isinstance(v, bool) for v in non_null):
        return "float"
    if all(isinstance(v, str) and _parse_date(v) for v in non_null):
        return "date"
    return "str"


# ---------------------------------------------------------------------------
# Pipeline steps
# ---------------------------------------------------------------------------

def read_json(path: str) -> list[dict]:
    with open(path, encoding="utf-8") as f:
        data = json.load(f)
    if isinstance(data, dict):
        data = [data]
    if not isinstance(data, list):
        raise ValueError("JSON root must be a list of objects or a single object")
    return data


def drop_all_empty(rows: list[dict]) -> list[dict]:
    return [r for r in rows if not all(_is_missing(v) for v in r.values())]


def deduplicate(rows: list[dict]) -> list[dict]:
    seen = set()
    unique = []
    for row in rows:
        key = tuple(sorted((k, str(v)) for k, v in row.items()))
        if key not in seen:
            seen.add(key)
            unique.append(row)
    return unique


def strip_whitespace(rows: list[dict]) -> list[dict]:
    cleaned = []
    for row in rows:
        new_row = {}
        for k, v in row.items():
            if isinstance(v, str):
                new_row[k] = v.strip()
            else:
                new_row[k] = v
        cleaned.append(new_row)
    return cleaned


def coerce_types(rows: list[dict]) -> list[dict]:
    return [{k: _coerce_value(v) for k, v in row.items()} for row in rows]


def fill_missing(rows: list[dict], columns: list[str], strategy: str = "median") -> list[dict]:
    if strategy == "drop":
        return [r for r in rows if not any(r.get(c) is None for c in columns)]

    col_types = {c: _detect_column_type([r.get(c) for r in rows]) for c in columns}

    numeric_fill = {}
    for c in columns:
        if col_types[c] in ("int", "float"):
            vals = [r[c] for r in rows if r.get(c) is not None]
            if vals:
                numeric_fill[c] = int(median(vals)) if col_types[c] == "int" else median(vals) if strategy == "median" else mean(vals)

    date_fill = {}
    for c in columns:
        if col_types[c] == "date":
            dates = sorted(r[c] for r in rows if r.get(c) is not None)
            if dates:
                date_fill[c] = dates[len(dates) // 2]

    filled = []
    for row in rows:
        new_row = {}
        for c in columns:
            v = row.get(c)
            if v is not None:
                new_row[c] = v
            elif c in numeric_fill:
                new_row[c] = numeric_fill[c]
            elif c in date_fill:
                new_row[c] = date_fill[c]
            else:
                new_row[c] = "N/A"
        filled.append(new_row)
    return filled


# ---------------------------------------------------------------------------
# CSV output
# ---------------------------------------------------------------------------

def write_csv(rows: list[dict], columns: list[str], output: str | None) -> None:
    def _format(v: Any) -> str:
        if v is None:
            return ""
        if isinstance(v, bool):
            return str(v).lower()
        return str(v)

    if output:
        with open(output, "w", newline="", encoding="utf-8") as f:
            writer = csv.DictWriter(f, fieldnames=columns, extrasaction="ignore")
            writer.writeheader()
            for row in rows:
                writer.writerow({c: _format(row.get(c)) for c in columns})
        print(f"Saved {len(rows)} rows to {output}", file=sys.stderr)
    else:
        writer = csv.DictWriter(sys.stdout, fieldnames=columns, extrasaction="ignore")
        writer.writeheader()
        for row in rows:
            writer.writerow({c: _format(row.get(c)) for c in columns})


# ---------------------------------------------------------------------------
# Pipeline orchestrator
# ---------------------------------------------------------------------------

def run_pipeline(
    source: str,
    output: str | None = None,
    strategy: str = "median",
) -> list[dict]:
    raw = read_json(source)
    original_count = len(raw)

    rows = drop_all_empty(raw)
    rows = deduplicate(rows)
    rows = strip_whitespace(rows)
    rows = coerce_types(rows)

    # Derive stable column order
    columns: list[str] = []
    for row in rows:
        for k in row:
            if k not in columns:
                columns.append(k)

    rows = fill_missing(rows, columns, strategy)

    cleaned_count = len(rows)
    removed = original_count - cleaned_count

    write_csv(rows, columns, output)

    col_types = {c: _detect_column_type([r.get(c) for r in rows]) for c in columns}
    print(f"\nRows: {original_count} -> {cleaned_count} ({removed} removed)", file=sys.stderr)
    print(f"Columns: {', '.join(f'{c} ({col_types[c]})' for c in columns)}", file=sys.stderr)
    print(f"Fill strategy: {strategy}", file=sys.stderr)

    return rows


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def main():
    parser = argparse.ArgumentParser(description="JSON → cleaned CSV pipeline")
    parser.add_argument("source", help="Path to input JSON file")
    parser.add_argument("-o", "--output", help="Write CSV to this file (default: stdout)")
    parser.add_argument("--fill-strategy", choices=["median", "mean", "drop"],
                        default="median", help="How to fill missing values (default: median)")
    args = parser.parse_args()

    run_pipeline(args.source, args.output, args.fill_strategy)


if __name__ == "__main__":
    main()
